import{parentPort,workerData}from'node:worker_threads';import{ReceiverJournal}from'../../../src/evidence-receiver/journal.mjs';const j=new ReceiverJournal(workerData.file);parentPort.postMessage('ready');if(Atomics.wait(new Int32Array(workerData.barrier),0,0,5000)==='timed-out')throw Error('receiver barrier not released');let status='REJECTED';try{j.accept(workerData.nonce,workerData.token,workerData.jti,Buffer.from('sealed'),{kind:'synthetic'},2000000001);status='STORED';}catch{}finally{j.close();}parentPort.postMessage(status);
